def lire(valeurs, i):
    if i >= 0 and i < len(valeurs):
        return valeurs[i]
    return None
print(lire([4, 8], 1))
print(lire([4, 8], 2))

def premier(valeurs):
    if len(valeurs) == 0:
        return None
    return valeurs[0]
print(premier([]))
print(premier([0]))

exercises.solution:
def lire_position(valeurs, i):
    if i >= 0 and i < len(valeurs):
        return valeurs[i]
    return None

def dernier_ou_none(valeurs):
    if len(valeurs) == 0:
        return None
    return valeurs[-1]

def moyenne_ou_none(valeurs):
    if len(valeurs) == 0:
        return None
    total = 0
    for valeur in valeurs:
        total = total + valeur
    return total / len(valeurs)
